{
  "properties": {
    "template": {
      "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
      "contentVersion": "1.0.0.0",
      "metadata": {
        "_generator": {
          "name": "bicep",
          "version": "0.11.9.63711",
          "templateHash": "10465450362821997478"
        }
      },
      "parameters": {
        "location": {
          "type": "string",
          "defaultValue": "[resourceGroup().location]"
        },
        "baseName": {
          "type": "string"
        },
        "dnsPrefix": {
          "type": "string"
        },
        "linuxAdminUsername": {
          "type": "string"
        },
        "sshRSAPublicKey": {
          "type": "string"
        }
      },
      "variables": {
        "osDiskSizeGB": 0,
        "agentCount": 3,
        "agentVMSize": "standard_f2s_v2",
        "resourceNamee": "[toLower(format('{0}{1}', parameters('baseName'), uniqueString(resourceGroup().id)))]"
      },
      "resources": [
        {
          "type": "Microsoft.ContainerService/managedClusters",
          "apiVersion": "2020-09-01",
          "name": "[variables('resourceNamee')]",
          "location": "[parameters('location')]",
          "properties": {
            "dnsPrefix": "[parameters('dnsPrefix')]",
            "agentPoolProfiles": [
              {
                "name": "agentpool",
                "osDiskSizeGB": "[variables('osDiskSizeGB')]",
                "count": "[variables('agentCount')]",
                "vmSize": "[variables('agentVMSize')]",
                "osType": "Linux",
                "mode": "System"
              }
            ],
            "linuxProfile": {
              "adminUsername": "[parameters('linuxAdminUsername')]",
              "ssh": {
                "publicKeys": [
                  {
                    "keyData": "[parameters('sshRSAPublicKey')]"
                  }
                ]
              }
            }
          },
          "identity": {
            "type": "SystemAssigned"
          }
        },
        {
          "type": "Microsoft.KeyVault/vaults",
          "apiVersion": "2022-07-01",
          "name": "[variables('resourceNamee')]",
          "location": "[parameters('location')]",
          "properties": {
            "sku": {
              "family": "A",
              "name": "standard"
            },
            "tenantId": "[subscription().tenantId]",
            "accessPolicies": [],
            "enabledForTemplateDeployment": true
          }
        },
        {
          "type": "Microsoft.KeyVault/vaults/secrets",
          "apiVersion": "2022-07-01",
          "name": "[format('{0}/{1}', variables('resourceNamee'), 'kubeconfig')]",
          "properties": {
            "value": "[listClusterAdminCredential(resourceId('Microsoft.ContainerService/managedClusters', variables('resourceNamee')), '2020-09-01').kubeconfigs[0].value]"
          },
          "dependsOn": [
            "[resourceId('Microsoft.ContainerService/managedClusters', variables('resourceNamee'))]",
            "[resourceId('Microsoft.KeyVault/vaults', variables('resourceNamee'))]"
          ]
        }
      ],
      "outputs": {
        "keyVaultId": {
          "type": "string",
          "value": "[resourceId('Microsoft.KeyVault/vaults', variables('resourceNamee'))]"
        },
        "secretName": {
          "type": "string",
          "value": "kubeconfig"
        }
      }
    },
    "parameters": {
      "dnsPrefix": {
        "value": "ps1029"
      },
      "sshRSAPublicKey": {
        "value": "ssh-rsa  ant@ant-mbp-work.lan"
      },
      "linuxAdminUsername": {
        "value": "adminps1029"
      },
      "baseName": {
        "value": "ps1029"
      }
    },
    "mode": "Incremental"
  }
}

